  &:disabled {
    cursor: not-allowed;
    opacity: 0.5;
  }

  svg {
    transition: transform 0.15s;
  }
}

.paki-select__toggle.open svg {
  transform: rotate(180deg);
}

// A lista usa position: fixed com posição/largura calculadas a partir do campo:
// acompanha a largura dele, não é recortada por overflow: hidden de cards e
