  border-radius: 12px;
  box-shadow: 0 8px 24px color-mix(in srgb, var(--color-text-primary) 12%, transparent);
  box-sizing: border-box;
  list-style: none;
  margin: 0;
  max-height: 260px;
  overflow: auto;
  padding: 6px;
  // top/left/width/max-height vêm do componente (posição real do campo).
  position: fixed;
  z-index: 1000;

  // Não herdar a tipografia do rótulo (uppercase, negrito, espaçamento).
  font-size: 14px;
  font-weight: 400;
  letter-spacing: normal;
  text-transform: none;

  li {
    border-radius: 8px;
    color: var(--color-text-primary);
    cursor: pointer;
    line-height: 1.35;
    overflow-wrap: anywhere;
    padding: 10px 12px;

    &:hover,
    &.active {
      background: var(--color-bg-page, var(--color-accent-tint));
    }

    &.selected {
      background: var(--color-accent-tint);
      color: var(--color-accent);
      font-weight: 600;
    }
  }

  mark {
    background: transparent;
    color: var(--color-accent);
    font-weight: 700;
  }
}

.paki-select__feedback {
  color: var(--color-text-faint);
  cursor: default;
  font-size: 12px;
  padding: 12px;
  text-align: center;

  &:hover {
    background: transparent !important;
  }
}

