}

.paki-sidenav__group-header {
  background: transparent;
  border: 0;
  color: inherit;
  cursor: pointer;
  text-align: left;
  width: 100%;

  &:hover {
    background: var(--color-accent-tint);
    color: var(--color-text-primary);
  }

  &[aria-expanded='true'] {
    color: var(--color-text-primary);

    .paki-sidenav__chevron {
      transform: rotate(180deg);
    }
  }
}

.paki-sidenav__icon {
